{% extends "base.html" %}
{% from "macros.html" import tier_color %}
{% block title %}Courses{% endblock %}
{% block content %}
<main class="container" id="main-content">
  <div class="page-header">
    <h2>Your Courses</h2>
    <a href="/courses/new" class="back-link" style="font-size:13px;">+ New course</a>
  </div>

  {% if courses %}
  <div class="course-list">
    {% for c in courses %}
    <div class="card" id="course-{{ c.course.id }}" style="position:relative;">
      <a href="/courses/{{ c.course.slug }}" class="card-link-overlay"></a>
      <div class="card-title-row">
        <strong class="card-title">{{ c.course.name }}</strong>
        <div style="display:flex; align-items:center; gap:8px; position:relative; z-index:1;">
          {% if c.mastery_avg is not none %}
          <span style="font-size:14px; font-weight:500; color:{{ tier_color(c.mastery_avg) }};">{{ c.mastery_avg|int }}%</span>
          {% endif %}
          <button
            class="btn-outline btn-small btn-danger"
            hx-delete="/courses/{{ c.course.slug }}"
            hx-target="#course-{{ c.course.id }}"
            hx-swap="outerHTML"
            hx-confirm="Delete '{{ c.course.name }}' and all its units, materials, and study data?"
            aria-label="Delete course"
          >Delete</button>
        </div>
      </div>
      {% if c.course.description %}
      <p class="card-description">{{ c.course.description }}</p>
      {% endif %}
      <div class="card-stats">
        {{ c.unit_count }} unit{{ 's' if c.unit_count != 1 else '' }} · {{ c.topic_count }} topic{{ 's' if c.topic_count != 1 else '' }}
      </div>
    </div>
    {% endfor %}
  </div>
  {% else %}
  <div class="empty-state">
    <div class="empty-state-icon">
      <svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><path d="M2 3h6a4 4 0 0 1 4 4v14a3 3 0 0 0-3-3H2z"/><path d="M22 3h-6a4 4 0 0 0-4 4v14a3 3 0 0 1 3-3h7z"/></svg>
    </div>
    <p>No courses yet. Create one to get started.</p>
    <a href="/courses/new" class="btn-primary" role="button">New Course</a>
  </div>
  {% endif %}
</main>
{% endblock %}

